func SpinnerCheckStyle(style int32) int32 {
	return style & ^(H_SCROLL | V_SCROLL)
}

func upcastSpinnerToControl(x *Spinner) *Control {
	if x == nil {
		return nil
	}
	return &x.Control
}

func init() {
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Fprintln(os.Stderr, "gowt: deferred init Spinner static{}:", r)
			}
		}()
		var lpWndClass *win32.WNDCLASS = win32.NewWNDCLASS()
		win32.OSGetClassInfo(int64(0), SpinnerEditClass, lpWndClass)
		SpinnerEditProc = lpWndClass.LpfnWndProc
		win32.OSGetClassInfo(int64(0), SpinnerUpDownClass, lpWndClass)
		SpinnerUpDownProc = lpWndClass.LpfnWndProc
	}()
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Fprintln(os.Stderr, "gowt: deferred init Spinner static{}:", r)
			}
		}()
		SpinnerLIMIT = 0x7FFFFFFF
	}()
}
